export function parseDuration(input: string): number {
    if (input.length === 0) {
        throw new Error("Input cannot be empty");
    }

    // Must not contain any whitespace
    if (/\s/.test(input)) {
        throw new Error("Input must not contain spaces");
    }

    const regex = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
    const match = input.match(regex);

    if (!match) {
        throw new Error("Invalid format");
    }

    // Ensure at least one unit is present
    if (!match[1] && !match[2] && !match[3]) {
        throw new Error("No time unit found");
    }

    const hours = match[1] ? parseInt(match[1], 10) : 0;
    const minutes = match[2] ? parseInt(match[2], 10) : 0;
    const seconds = match[3] ? parseInt(match[3], 10) : 0;

    // All parsed values must be integers (regex already guarantees digits)
    // but we double‑check for safety
    if (isNaN(hours) || isNaN(minutes) || isNaN(seconds)) {
        throw new Error("Non‑integer value detected");
    }

    return hours * 3600 + minutes * 60 + seconds;
}
