type SemVer = {
    major: number;
    minor: number;
    patch: number;
    prerelease: string[]; // empty array means no prerelease
};

function parseSemVer(v: string): SemVer {
    const semverRegex = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
    const match = semverRegex.exec(v);
    if (!match) throw new Error(`Invalid version: ${v}`);

    const [, majorStr, minorStr, patchStr, prereleaseStr] = match;

    const major = Number(majorStr);
    const minor = Number(minorStr);
    const patch = Number(patchStr);

    const prerelease = prereleaseStr ? prereleaseStr.split('.') : [];

    // Validate each prerelease identifier (numeric identifiers must not have leading zeros)
    for (const id of prerelease) {
        if (id.length === 0) throw new Error(`Invalid prerelease identifier in ${v}`);
        if (/^[0-9]+$/.test(id) && id.length > 1 && id.startsWith('0')) {
            throw new Error(`Invalid numeric prerelease identifier with leading zero in ${v}`);
        }
        if (!/^[0-9A-Za-z-]+$/.test(id)) {
            throw new Error(`Invalid prerelease identifier characters in ${v}`);
        }
    }

    return { major, minor, patch, prerelease };
}

function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
    const aNum = /^[0-9]+$/.test(a);
    const bNum = /^[0-9]+$/.test(b);

    if (aNum && bNum) {
        const diff = Number(a) - Number(b);
        return diff < 0 ? -1 : diff > 0 ? 1 : 0;
    }

    if (aNum && !bNum) return -1; // numeric < alphanumeric
    if (!aNum && bNum) return 1;  // alphanumeric > numeric

    // both alphanumeric: lexical ASCII order
    return a < b ? -1 : a > b ? 1 : 0;
}

export function compareSemver(a: string, b: string): -1 | 0 | 1 {
    const av = parseSemVer(a);
    const bv = parseSemVer(b);

    // Compare core version
    if (av.major !== bv.major) return av.major < bv.major ? -1 : 1;
    if (av.minor !== bv.minor) return av.minor < bv.minor ? -1 : 1;
    if (av.patch !== bv.patch) return av.patch < bv.patch ? -1 : 1;

    const aPre = av.prerelease;
    const bPre = bv.prerelease;

    // If both have no prerelease, they are equal
    if (aPre.length === 0 && bPre.length === 0) return 0;
    // A version without prerelease is higher than one with prerelease
    if (aPre.length === 0) return 1;
    if (bPre.length === 0) return -1;

    // Compare prerelease identifiers
    const len = Math.max(aPre.length, bPre.length);
    for (let i = 0; i < len; i++) {
        const aId = aPre[i];
        const bId = bPre[i];
        if (aId === undefined) return -1; // a has fewer identifiers -> lower
        if (bId === undefined) return 1;  // b has fewer identifiers -> lower
        const cmp = compareIdentifiers(aId, bId);
        if (cmp !== 0) return cmp;
    }

    return 0;
}
