function buildOrder(deps: Record<string, string[]>): string[] {
    // Collect all nodes
    const nodes = new Set<string>();
    for (const pkg of Object.keys(deps)) {
        nodes.add(pkg);
        for (const d of deps[pkg]) nodes.add(d);
    }

    // Build adjacency list (edges from dependency -> dependent) and indegree map
    const adj = new Map<string, Set<string>>();
    const indeg = new Map<string, number>();
    for (const n of nodes) {
        adj.set(n, new Set());
        indeg.set(n, 0);
    }

    for (const [pkg, depList] of Object.entries(deps)) {
        const uniq = new Set(depList); // ignore duplicate deps
        for (const d of uniq) {
            // edge d -> pkg
            adj.get(d)!.add(pkg);
            indeg.set(pkg, indeg.get(pkg)! + 1);
        }
    }

    // Simple min‑heap for strings
    class MinHeap {
        private data: string[] = [];
        private compare(a: string, b: string) { return a < b; }

        push(item: string) {
            this.data.push(item);
            this.bubbleUp(this.data.length - 1);
        }
        pop(): string | undefined {
            if (this.data.length === 0) return undefined;
            const top = this.data[0];
            const end = this.data.pop()!;
            if (this.data.length > 0) {
                this.data[0] = end;
                this.sinkDown(0);
            }
            return top;
        }
        size() { return this.data.length; }

        private bubbleUp(idx: number) {
            const item = this.data[idx];
            while (idx > 0) {
                const parentIdx = Math.floor((idx - 1) / 2);
                const parent = this.data[parentIdx];
                if (!this.compare(item, parent)) break;
                this.data[parentIdx] = item;
                this.data[idx] = parent;
                idx = parentIdx;
            }
        }
        private sinkDown(idx: number) {
            const length = this.data.length;
            const item = this.data[idx];
            while (true) {
                let leftIdx = 2 * idx + 1;
                let rightIdx = 2 * idx + 2;
                let swapIdx: number | null = null;

                if (leftIdx < length) {
                    const left = this.data[leftIdx];
                    if (this.compare(left, item)) swapIdx = leftIdx;
                }
                if (rightIdx < length) {
                    const right = this.data[rightIdx];
                    if (this.compare(right, swapIdx === null ? item : this.data[swapIdx])) swapIdx = rightIdx;
                }
                if (swapIdx === null) break;
                this.data[idx] = this.data[swapIdx];
                this.data[swapIdx] = item;
                idx = swapIdx;
            }
        }
    }

    const heap = new MinHeap();
    for (const n of nodes) {
        if (indeg.get(n)! === 0) heap.push(n);
    }

    const result: string[] = [];
    while (heap.size() > 0) {
        const cur = heap.pop()!;
        result.push(cur);
        for (const neigh of adj.get(cur)!) {
            indeg.set(neigh, indeg.get(neigh)! - 1);
            if (indeg.get(neigh)! === 0) heap.push(neigh);
        }
    }

    if (result.length !== nodes.size) {
        throw new Error("cycle detected");
    }
    return result;
}
