export function slugify(s: string): string {
  // Normalize to decompose accents, remove diacritics, lower case
  const normalized = s
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
  // Split on any non-alphanumeric characters (including whitespace and punctuation)
  const parts = normalized.split(/[^a-z0-9]+/).filter(Boolean);
  // Join with single hyphens
  return parts.join('-');
}

