type Parsed = {
    major: number;
    minor: number;
    patch: number;
    prerelease: string[] | null;
};

function parseVersion(v: string): Parsed {
    const regex = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
    const m = v.match(regex);
    if (!m) throw new Error(`Invalid version: ${v}`);

    const [, majorStr, minorStr, patchStr, prereleaseStr] = m;

    const major = Number(majorStr);
    const minor = Number(minorStr);
    const patch = Number(patchStr);

    let prerelease: string[] | null = null;
    if (prereleaseStr !== undefined) {
        prerelease = prereleaseStr.split('.');
        for (const id of prerelease) {
            if (!/^[0-9A-Za-z-]+$/.test(id)) {
                throw new Error(`Invalid version: ${v}`);
            }
            if (/^\d+$/.test(id) && id.length > 1 && id.startsWith('0')) {
                // numeric identifier with leading zeros
                throw new Error(`Invalid version: ${v}`);
            }
        }
    }

    return { major, minor, patch, prerelease };
}

function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
    const aNum = /^\d+$/.test(a);
    const bNum = /^\d+$/.test(b);
    if (aNum && bNum) {
        const diff = Number(a) - Number(b);
        return diff < 0 ? -1 : diff > 0 ? 1 : 0;
    }
    if (aNum && !bNum) return -1; // numeric < alphanumeric
    if (!aNum && bNum) return 1;
    // both alphanumeric
    return a < b ? -1 : a > b ? 1 : 0;
}

export function compareSemver(a: string, b: string): -1 | 0 | 1 {
    const A = parseVersion(a);
    const B = parseVersion(b);

    if (A.major !== B.major) return A.major < B.major ? -1 : 1;
    if (A.minor !== B.minor) return A.minor < B.minor ? -1 : 1;
    if (A.patch !== B.patch) return A.patch < B.patch ? -1 : 1;

    const preA = A.prerelease;
    const preB = B.prerelease;

    if (preA === null && preB === null) return 0;
    if (preA === null) return 1; // release > pre-release
    if (preB === null) return -1;

    const len = Math.max(preA.length, preB.length);
    for (let i = 0; i < len; i++) {
        const idA = preA[i];
        const idB = preB[i];
        if (idA === undefined) return -1; // shorter set has lower precedence
        if (idB === undefined) return 1;
        const cmp = compareIdentifiers(idA, idB);
        if (cmp !== 0) return cmp;
    }
    return 0;
}
