function buildOrder(deps: Record<string, string[]>): string[] {
  // collect all package names
  const nodes = new Set<string>();
  for (const pkg in deps) {
    nodes.add(pkg);
    for (const d of deps[pkg]) nodes.add(d);
  }

  // adjacency list (edge: dependency -> dependent) and indegree map
  const adj = new Map<string, Set<string>>();
  const indegree = new Map<string, number>();
  for (const n of nodes) {
    adj.set(n, new Set());
    indegree.set(n, 0);
  }

  for (const pkg in deps) {
    const uniq = Array.from(new Set(deps[pkg])); // deduplicate edges
    for (const d of uniq) {
      // edge d -> pkg
      if (!adj.get(d)!.has(pkg)) {
        adj.get(d)!.add(pkg);
        indegree.set(pkg, indegree.get(pkg)! + 1);
      }
    }
  }

  // simple binary min‑heap for lexicographically smallest node selection
  class MinHeap {
    private data: string[] = [];
    private less(a: string, b: string): boolean { return a < b; }

    push(x: string): void {
      this.data.push(x);
      this.bubbleUp(this.data.length - 1);
    }

    private bubbleUp(i: number): void {
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (this.less(this.data[i], this.data[p])) {
          [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
          i = p;
        } else break;
      }
    }

    pop(): string | undefined {
      if (this.data.length === 0) return undefined;
      const top = this.data[0];
      const end = this.data.pop()!;
      if (this.data.length) {
        this.data[0] = end;
        this.sink(0);
      }
      return top;
    }

    private sink(i: number): void {
      const n = this.data.length;
      while (true) {
        let left = i * 2 + 1;
        let right = left + 1;
        let smallest = i;
        if (left < n && this.less(this.data[left], this.data[smallest])) smallest = left;
        if (right < n && this.less(this.data[right], this.data[smallest])) smallest = right;
        if (smallest !== i) {
          [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
          i = smallest;
        } else break;
      }
    }

    size(): number { return this.data.length; }
  }

  const heap = new MinHeap();
  for (const n of nodes) if (indegree.get(n)! === 0) heap.push(n);

  const order: string[] = [];
  while (heap.size()) {
    const node = heap.pop()!;
    order.push(node);
    for (const nxt of adj.get(node)!) {
      indegree.set(nxt, indegree.get(nxt)! - 1);
      if (indegree.get(nxt)! === 0) heap.push(nxt);
    }
  }

  if (order.length !== nodes.size) {
    throw new Error("cycle");
  }
  return order;
}
