function parseCsvLine(line: string): string[] {
    // Empty line represents a single empty field
    if (line.length === 0) return [''];

    const fields: string[] = [];
    const len = line.length;
    let i = 0;

    while (i <= len) {
        // End of string: break (handled trailing empty after loop)
        if (i === len) break;

        // Empty field (consecutive commas or leading comma)
        if (line[i] === ',') {
            fields.push('');
            i++; // skip the comma
            continue;
        }

        let field = '';

        // Quoted field
        if (line[i] === '"') {
            i++; // skip opening quote
            while (true) {
                if (i >= len) {
                    throw new Error('Unterminated quoted field');
                }
                const ch = line[i];
                if (ch === '"') {
                    // escaped quote?
                    if (i + 1 < len && line[i + 1] === '"') {
                        field += '"';
                        i += 2;
                        continue;
                    }
                    // closing quote
                    i++; // move past closing quote
                    // after a closing quote only a comma or end of line is allowed
                    if (i < len && line[i] !== ',') {
                        throw new Error('Invalid character after closing quote');
                    }
                    break;
                } else {
                    field += ch;
                    i++;
                }
            }
        } else {
            // Unquoted field: read until next comma or end
            while (i < len && line[i] !== ',') {
                field += line[i];
                i++;
            }
        }

        fields.push(field);

        // If next character is a comma, skip it (separator)
        if (i < len && line[i] === ',') {
            i++;
        }
    }

    // If the line ends with a comma, that denotes a trailing empty field
    if (line.endsWith(',')) {
        fields.push('');
    }

    return fields;
}
