export function slugify(s: string): string {
  // Normalize to NFD to separate accents, then remove diacritic marks
  const normalized = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  // Convert to lowercase and replace any sequence of non‑alphanumeric characters with a hyphen
  const hyphenated = normalized
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-');
  // Trim leading and trailing hyphens
  return hyphenated.replace(/^[-]+|[-]+$/g, '');
